const m_extra_shim = (() => {
function takeKeys(note, keys) {
  const taken = {};
  if (!note) return { taken, rest: note };
  const rest = [];
  for (const line of String(note).split('\n')) {
    const m = /^([a-z][a-z0-9-]*):\s*(.*)$/.exec(line);
    if (m && keys.has(m[1])) taken[m[1]] = m[2].trim();
    else rest.push(line);
  }
  return { taken, rest: rest.join('\n') };
}

function hasKey(note, key) {
  return new RegExp(`^${key}:`, 'm').test(note || '');
}

return { takeKeys, hasKey };
})();

const m_authors_shim = (() => {
const ET_AL = { uk: 'та ін.', ru: 'и др.', en: 'et al.' };

function markManyAuthors(item, prefs) {
  const authors = item.author || [];
  if (authors.length < 4 || item.curator) return;
  const first = authors[0];
  const name = prefs.nameOrder === 'given-family'
    ? [first.given, first.family].filter(Boolean).join(' ')
    : [first.family, first.given].filter(Boolean).join(' ');
  const lang = (item.language || 'uk').slice(0, 2);
  item.curator = [{ literal: `${name} ${ET_AL[lang] || ET_AL.uk}` }];
}

return { markManyAuthors };
})();

